window.kbPageData["views/entry/k-fd7c22a85765faa6"] = {"key":"entry/k-fd7c22a85765faa6","state":{"route":"entry/k-fd7c22a85765faa6"},"node":{"id":"k-fd7c22a85765faa6","mode":"k","title":"县级以上地方政府责成强制拆除的条件","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["县级以上地方政府责成有关部门实施强制拆除的条件"],"qs":["江苏 2023 B类 行测#19"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"需核对批复前是否已作出并送达责令停止建设或限期拆除的决定，以及当事人是否继续建设或逾期未拆除。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：区政府作出批复，同意对上述违法建筑实施强制拆除","review":{"definition":"原题引文：区政府作出批复，同意对上述违法建筑实施强制拆除","explanation":"第19题的C项对应区政府依法作出强拆决定、责成街道办牵头实施的权限。题干和原案公开案情均载明规资局认定违建以及区政府随后批复强拆。认定违建的公告只交代了建筑性质，适用第六十八条还须核实是否已有法定前置决定及当事人是否未履行。原案裁定处理的是陈某诉请街道办履行批复能否受理。","references":[{"source":"web-804c3171bbc45bdd","location":"第六十八条","quote":"当事人不停止建设或者逾期不拆除的"},{"source":"web-8f9d20696d66dd54","location":"案情，2019年10月批复","quote":"同意对上述违法建、构筑物实施强制拆除"}],"evidence":"区政府作出批复，同意对上述违法建筑实施强制拆除","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#19":{"paper":"江苏 2023 B类 行测","n":19,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",8],"card":"a980fa5fcb5dfb5bac46689a","links":[{"id":"k-fd7c22a85765faa6","role":"解题依据","why":"在主管部门作出相关决定且当事人仍不履行后，县级以上地方政府可以责成有关部门采取强制措施。"}]}},"terms":{},"references":{"web-804c3171bbc45bdd":{"name":"《中华人民共和国城乡规划法》（2019年修正）","url":"https://www.mee.gov.cn/ywgz/fgbz/fl/201906/t20190605_705768.shtml"},"web-8f9d20696d66dd54":{"name":"《人民法院报》陈某强诉重庆江北区石马河街道办履行强拆批复案","url":"https://www.sdcourt.gov.cn/wfhtqfy/443063/443232/7281449/index.html"}},"topics":[],"units":{"k-fd7c22a85765faa6":[["江苏 2023 B类 行测#19"]]}};
